use std::time::Instant;

fn build_input() -> Vec<u8> {
    let mut data = Vec::with_capacity(8 * 1024 * 1024);
    for block in 0..4096u32 {
        let header = format!("frame-{block:04}-lz4-benchmark-");
        for _ in 0..32 {
            data.extend_from_slice(header.as_bytes());
            data.extend_from_slice(&block.to_le_bytes());
        }
        data.extend((0..512).map(|i| ((i as u32 + block * 13) & 0xff) as u8));
        data.extend(std::iter::repeat_n((block & 0xff) as u8, 768));
    }
    data
}

fn main() {
    let input = build_input();
    let src_size = input.len() as i32;
    let bound = unsafe { lz4_raw::src::lz4::LZ4_compressBound(src_size) };
    let mut compressed = vec![0u8; bound as usize];
    let mut restored = vec![0u8; input.len()];

    let warm = unsafe {
        lz4_raw::src::lz4::LZ4_compress_default(
            input.as_ptr() as *const i8,
            compressed.as_mut_ptr() as *mut i8,
            src_size,
            bound,
        )
    };
    assert!(warm > 0);
    let decompressed = unsafe {
        lz4_raw::src::lz4::LZ4_decompress_safe(
            compressed.as_ptr() as *const i8,
            restored.as_mut_ptr() as *mut i8,
            warm,
            restored.len() as i32,
        )
    };
    assert_eq!(decompressed, src_size);
    assert_eq!(&restored[..], &input[..]);

    let compress_iters = 200;
    let start = Instant::now();
    let mut last_size = 0i32;
    for _ in 0..compress_iters {
        last_size = unsafe {
            lz4_raw::src::lz4::LZ4_compress_default(
                input.as_ptr() as *const i8,
                compressed.as_mut_ptr() as *mut i8,
                src_size,
                bound,
            )
        };
        assert!(last_size > 0);
    }
    let compress_elapsed = start.elapsed();

    let decompress_iters = 400;
    let start = Instant::now();
    for _ in 0..decompress_iters {
        let got = unsafe {
            lz4_raw::src::lz4::LZ4_decompress_safe(
                compressed.as_ptr() as *const i8,
                restored.as_mut_ptr() as *mut i8,
                last_size,
                restored.len() as i32,
            )
        };
        assert_eq!(got, src_size);
    }
    let decompress_elapsed = start.elapsed();

    println!("input_bytes={}", input.len());
    println!("compressed_bytes={}", last_size);
    println!("compress_iters={compress_iters}");
    println!("compress_ns_total={}", compress_elapsed.as_nanos());
    println!("decompress_iters={decompress_iters}");
    println!("decompress_ns_total={}", decompress_elapsed.as_nanos());
}

